public class InnerConnectorV2ProviderFactory(Action<Humidifier.SecurityHub.ConnectorV2Types.Provider> factoryAction = null) : SubResourceFactory<Humidifier.SecurityHub.ConnectorV2Types.Provider>
{

    internal InnerConnectorV2ServiceNowProviderConfigurationFactory ServiceNowFactory { get; set; }

    internal InnerConnectorV2AzureProviderConfigurationFactory AzureFactory { get; set; }

    internal InnerConnectorV2JiraCloudProviderConfigurationFactory JiraCloudFactory { get; set; }

    protected override Humidifier.SecurityHub.ConnectorV2Types.Provider Create()
    {
        var providerResult = CreateProvider();
        factoryAction?.Invoke(providerResult);

        return providerResult;
    }

    private Humidifier.SecurityHub.ConnectorV2Types.Provider CreateProvider()
    {
        var providerResult = new Humidifier.SecurityHub.ConnectorV2Types.Provider();

        return providerResult;
    }
    public override void CreateChildren(Humidifier.SecurityHub.ConnectorV2Types.Provider result)
    {
        base.CreateChildren(result);

        result.ServiceNow ??= ServiceNowFactory?.Build();
        result.Azure ??= AzureFactory?.Build();
        result.JiraCloud ??= JiraCloudFactory?.Build();
    }

} // End Of Class

